  '  const HOME = { az: -62, el: 14, zoom: 1, tx: 0, ty: 0 };',
  '''  // The plate mounts on +X, so the camera opens looking down +X with a small
  // offset -- dead-on is edge-on to a flat plate and reads as a stripe. Getting
  // this wrong hides the implant behind the bone, which is the one thing the
  // page exists to show.
  const HOME = { az: 74, el: 12, zoom: 1, tx: 0, ty: 0 };''')

