  // "8,596", which beside a "1,5 mm" limit reads as three thousand times over.
  const NUM = new Intl.NumberFormat("en-US", { maximumFractionDigits: 3 });
  const fmt = (v) => (v === null || v === undefined ? "\\u2014" : NUM.format(+v));''')

